import{_ as e,o,c as a,ae as d}from"./chunks/framework.BX6FPmO9.js";const p=JSON.parse('{"title":"Agentic 整合檢閱與路線圖 — Agent-Executable Portal","description":"","frontmatter":{},"headers":[],"relativePath":"product/agentic-integration-review.md","filePath":"product/agentic-integration-review.md"}'),r={name:"product/agentic-integration-review.md"};function c(l,t,i,n,s,h){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="agentic-整合檢閱與路線圖-—-agent-executable-portal" tabindex="-1">Agentic 整合檢閱與路線圖 — Agent-Executable Portal <a class="header-anchor" href="#agentic-整合檢閱與路線圖-—-agent-executable-portal" aria-label="Permalink to &quot;Agentic 整合檢閱與路線圖 — Agent-Executable Portal&quot;">​</a></h1><blockquote><p>建立日：2026-07-09 · 對齊：<a href="./ai-experience-plan.html">ai-experience-plan.md</a>（dual-path）、<a href="./interface-roadmap.html">interface-roadmap.md</a>（歷史 sitemap）。階段 SSOT 不在本公開 repo。 依據：Gartner 2026-07 預測——至 2030 年約 2,340 億美元（約 20%）企業 SaaS 支出暴露於 agentic arbitrage；產品價值從「畫面功能」移向「能否被 Agent 安全、可控、可稽核地呼叫」。</p></blockquote><h2 id="_0-結論先講" tabindex="-1">0. 結論先講 <a class="header-anchor" href="#_0-結論先講" aria-label="Permalink to &quot;0. 結論先講&quot;">​</a></h2><p>本 portal 的定位不是「AI catalog」，而是：</p><blockquote><p><strong>Agent 可執行、人可接管、來源可驗證、權限可治理的資料與 API portal。</strong></p></blockquote><p>檢閱結果：五大趨勢中，「規格與驗證」與「雙介面」基礎最強（CI 契約鏈、MCP gateway 已落地）；最大缺口在 <strong>tool contract schema 化</strong>與<strong>審計實體化</strong>——兩者正是「信任層」的地基，應優先於新增任何 AI 功能。</p><h2 id="_1-五趨勢-×-現況對照" tabindex="-1">1. 五趨勢 × 現況對照 <a class="header-anchor" href="#_1-五趨勢-×-現況對照" aria-label="Permalink to &quot;1. 五趨勢 × 現況對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>趨勢</th><th>現況</th><th>證據（repo）</th><th>主要差距</th></tr></thead><tbody><tr><td>1</td><td>應用經濟學：賣可衡量任務結果，非 seat</td><td>🔄 部分</td><td><code>labs/eval-runner/</code>（golden fixtures + CI <code>eval:offline</code>）可衡量任務成功率</td><td>無 task-level 成效指標（執行次數、完成率、接手率）對外呈現；eval 不擋 PR</td></tr><tr><td>2</td><td>Context 是差異化，不是 UI</td><td>🔄 部分</td><td><code>content/context-packs/</code> + <code>api.context.*</code>、<code>specs/datacontracts/</code>、<code>catalog-search.dictionary</code>、<code>docs/architecture/ai-product/memory-policy.md</code>；<s>glossary 未接入</s> ✅ 2026-08-11 已接入（見下方證據）</td><td>request history / 機構記憶未累積；policy 未接入 agent context（glossary 缺口已關閉）</td></tr><tr><td>3</td><td>雙介面：人 + Agent</td><td>✅ 偏強</td><td>dual-path SSOT（ai-experience-plan）、MCP gateway（<code>well-known.mcp[.]json</code> + 4 tools）、agent-core tool allowlist（5 tools）</td><td>tool 只有 allowlist 字串，無 per-tool I/O schema、權限標籤、discovery metadata</td></tr><tr><td>4</td><td>信任與治理是產品本身</td><td>🔄 部分</td><td>OPA rego + in-process evaluator、HITL 確認卡（<code>MetadataAssetDetailView</code>）、輸入層 guardrails、source citation（<code>chat.contract.ts</code> sources）</td><td><code>auditLogged</code> 僅為布林，<strong>無 audit log 落盤與查詢</strong>；guardrails 缺輸出層；RBAC 為模擬 role</td></tr><tr><td>5</td><td>規格與驗證 &gt; 純寫碼</td><td>✅ 強</td><td>OpenAPI+Zod 雙軌 SoT（ADR <code>spec-driven-contracts-and-sot.md</code>）、CI：Spectral + codegen drift check + rego tests + eval</td><td>tool contract 未納入同一條 Spec→Contract→Test 鏈</td></tr></tbody></table><blockquote><p><strong>趨勢 2 gap closed（glossary）— 2026-08-11 / T-2026-071</strong>：<code>scripts/sync-domain-glossary.mjs</code> 把 <code>platform-command/specs/domain/*.yaml</code>（engineering + pm，48 terms）冪等同步進 <code>content/context-packs/ecosystem-glossary/glossary.json</code>；<code>packages/agent-core/src/rag/local-store.ts</code> 的 <code>resolveRagCorpus()</code> 在 <code>includeDefaults</code>（預設）時把此 pack 併入<strong>每一個</strong> RAG corpus（不論當前 active pack 為何），所以 LUI 隨時可檢索到生態詞彙。每筆 glossary entry 帶 <code>source</code>（如 <code>platform-command:specs/domain/pm.yaml#sprint</code>），經 <code>LocalDoc.source</code> → <code>LuiSource.source</code> → <code>luiSourceSchema</code>（<code>chat.contract.ts</code>）一路透傳到 <code>internal.final</code>/<code>final</code> SSE 事件，<code>ChatInterface.tsx</code> 在來源連結下方顯示該引用字串。剩餘缺口（policy 未接入、機構記憶）維持開放，見上表。</p></blockquote><h2 id="_2-三層架構對照" tabindex="-1">2. 三層架構對照 <a class="header-anchor" href="#_2-三層架構對照" aria-label="Permalink to &quot;2. 三層架構對照&quot;">​</a></h2><h3 id="_2-1-human-control-plane-人可監督、接管" tabindex="-1">2.1 Human Control Plane（人可監督、接管） <a class="header-anchor" href="#_2-1-human-control-plane-人可監督、接管" aria-label="Permalink to &quot;2.1 Human Control Plane（人可監督、接管）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>現況</th></tr></thead><tbody><tr><td>Chat / LUI + 降級接手</td><td>✅ <code>ChatInterface</code> + <code>AiFallbackPanel</code>（失敗帶 <code>?q=</code>+<code>?type=</code> 預填手動頁）</td></tr><tr><td>Catalog / 篩選 / 字典</td><td>✅ <code>/catalog-search</code>（URL 契約 <code>catalog-search-url.ts</code>）</td></tr><tr><td>資產詳情 + 血緣</td><td>🔄 <code>metadata.$assetId</code>；DAG 視覺化 T-2026-016</td></tr><tr><td>申請追蹤 / 審核中心</td><td>⬜ 申請畫面 T-2026-023；審核中心未規劃為獨立頁</td></tr><tr><td>Audit log 檢視頁</td><td>⬜ 無（依賴 §3 階段五）</td></tr><tr><td>全站導覽 / Dashboard</td><td>⬜ interface-roadmap R1</td></tr><tr><td>Developer Hub / API explorer</td><td>⬜ interface-roadmap R3（<code>/developers/apis/$apiId</code> 純規劃）</td></tr></tbody></table><h3 id="_2-2-agent-tool-layer-agent-可呼叫" tabindex="-1">2.2 Agent Tool Layer（Agent 可呼叫） <a class="header-anchor" href="#_2-2-agent-tool-layer-agent-可呼叫" aria-label="Permalink to &quot;2.2 Agent Tool Layer（Agent 可呼叫）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>現況</th></tr></thead><tbody><tr><td>內部 tools（allowlist + 執行器）</td><td>✅ <code>items.lookup</code> <code>metadata.lookup</code> <code>context.resolve_metric</code> <code>context.bindings</code> <code>rag.search</code>（經 Zod 契約 parse、timeout、env gate）</td></tr><tr><td>MCP tools</td><td>✅ <code>metadata.search</code> <code>metadata.get</code> <code>metadata.lineage</code> <code>policy.evaluate</code>（stateless，lineage &gt;6 節點走 async task）</td></tr><tr><td>per-tool I/O schema + 權限/審計標籤</td><td>⬜ tool-boundary.md 標「預留」；MCP arguments 為寬鬆 <code>z.record</code></td></tr><tr><td>申請類 tools（draft / submit）</td><td>⬜ route 已有（<code>api.metadata.access-requests*</code>）但未包成 agent tool</td></tr><tr><td>Tool discovery（能力目錄）</td><td>🔄 MCP discover 有 tool 清單，缺 schema 與風險層級註記</td></tr></tbody></table><h3 id="_2-3-trust-governance-layer-不亂做事" tabindex="-1">2.3 Trust &amp; Governance Layer（不亂做事） <a class="header-anchor" href="#_2-3-trust-governance-layer-不亂做事" aria-label="Permalink to &quot;2.3 Trust &amp; Governance Layer（不亂做事）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>現況</th></tr></thead><tbody><tr><td>Policy check（OPA）</td><td>✅ <code>specs/policies/access-request.rego</code> + evaluator + tests</td></tr><tr><td>HITL（need_approval → 人工確認）</td><td>✅ 申請流程有；未泛化為「風險層級 × 動作」框架</td></tr><tr><td>輸入 guardrails</td><td>✅ <code>tools/guardrails.ts</code>（長度、prompt-injection）</td></tr><tr><td>輸出 guardrails / PII 遮罩應用</td><td>⬜ <code>mask_fields</code> 決策存在，未應用於 tool 輸出；R4 M2</td></tr><tr><td>Source citation</td><td>✅ <code>luiSourceSchema</code> + final 事件 sources</td></tr><tr><td>Audit trail（落盤、可查）</td><td>⬜ 僅 response 布林</td></tr><tr><td>離線評測</td><td>✅ eval-runner + CI；⬜ 不擋 PR</td></tr><tr><td>Observability</td><td>🔄 Langfuse env-gated no-op，trace 待 Phase 2</td></tr><tr><td>真實 auth / RBAC</td><td>⬜ 刻意維持 role 模擬（roadmap 明示）</td></tr></tbody></table><h2 id="_3-五階段路線圖-對齊既有-phase-r-t" tabindex="-1">3. 五階段路線圖（對齊既有 Phase / R / T） <a class="header-anchor" href="#_3-五階段路線圖-對齊既有-phase-r-t" aria-label="Permalink to &quot;3. 五階段路線圖（對齊既有 Phase / R / T）&quot;">​</a></h2><p>原則：<strong>不追 fully autonomous</strong>。每階段的 agent 能力提升，必須伴隨同等的治理能力，否則不進下一階段。</p><h3 id="階段一-來源可驗證的-ai-搜尋-—-✅-大致完成-收尾" tabindex="-1">階段一：來源可驗證的 AI 搜尋 — ✅ 大致完成，收尾 <a class="header-anchor" href="#階段一-來源可驗證的-ai-搜尋-—-✅-大致完成-收尾" aria-label="Permalink to &quot;階段一：來源可驗證的 AI 搜尋 — ✅ 大致完成，收尾&quot;">​</a></h3><p>回答必附來源，資料來自 catalog / spec / policy，非模型生成。</p><ul><li>待補：AI 代填視覺標記（缺口②）、<code>AiFallbackPanel</code> 逾時與信心不足觸發（T-2026-020）。</li><li><strong>驗收</strong>：六條 dual-path 任務的 AI 路徑皆帶 sources；E2E 雙軌覆蓋；eval golden set 涵蓋「無來源即失敗」案例。</li></ul><h3 id="階段二-tool-contract-schema-化-—-🔄-最優先" tabindex="-1">階段二：Tool contract schema 化 — 🔄 最優先 <a class="header-anchor" href="#階段二-tool-contract-schema-化-—-🔄-最優先" aria-label="Permalink to &quot;階段二：Tool contract schema 化 — 🔄 最優先&quot;">​</a></h3><p>把 allowlist 升級為 tool registry：每個 tool 定義 Zod I/O schema、timeout、<strong>風險層級（low / medium / high）</strong>、所需 role、是否需 HITL、是否強制 audit。落實 tool-boundary.md 的預留設計。</p><ul><li>新增契約：<code>packages/shared-contracts/src/tool.contract.ts</code>（遵守「app/** 不新增 contract」邊界）。</li><li>MCP <code>z.record</code> 換成 per-tool schema；discover 回傳 schema + 風險註記。</li><li>申請能力包成 tools：<code>access_request.draft</code>（medium）、<code>access_request.submit</code>（high, HITL 必停）。</li><li><strong>驗收</strong>：registry 內無 schema 的 tool 無法註冊（型別層擋）；CI 契約鏈涵蓋 tool contract（codegen drift check 同款手法）。</li></ul><h3 id="階段三-hitl-泛化-—-依賴階段二" tabindex="-1">階段三：HITL 泛化 — 依賴階段二 <a class="header-anchor" href="#階段三-hitl-泛化-—-依賴階段二" aria-label="Permalink to &quot;階段三：HITL 泛化 — 依賴階段二&quot;">​</a></h3><p>從「申請流程專用」泛化為「風險層級驅動」：low 直接執行、medium 產生草稿、high 停下等人 approve / edit / reject。</p><ul><li>申請畫面（T-2026-023）+ 審核中心頁（Human Control Plane 補位）。</li><li>AI 代填欄位視覺標記全站化（缺口②延伸）。</li><li><strong>驗收</strong>：high-risk tool 無人工確認即無法執行（伺服器端強制，非 UI 擋）；E2E 驗 approve / edit / reject 三徑。</li></ul><h3 id="階段四-mcp-openapi-對外化-—-🔄-已起步-補治理再開放" tabindex="-1">階段四：MCP / OpenAPI 對外化 — 🔄 已起步，補治理再開放 <a class="header-anchor" href="#階段四-mcp-openapi-對外化-—-🔄-已起步-補治理再開放" aria-label="Permalink to &quot;階段四：MCP / OpenAPI 對外化 — 🔄 已起步，補治理再開放&quot;">​</a></h3><p>MCP gateway 已存在；對外開放前先補齊階段二、三，否則等於輸出無治理的能力。</p><ul><li>Developer Hub（R3）：<code>/developers</code> API explorer + try-it sandbox（fork-on-write，見 interface-roadmap §4.4），讓「人的 API 文件」與「Agent 的 MCP discover」同源。</li><li>外部 agent 接入的 identity 傳遞（即使 role 仍模擬，介面先定義）。</li><li><strong>驗收</strong>：外部 AI workspace 可經 MCP 完成「搜尋 → 查血緣 → 政策預審 → 申請草稿」全鏈，且 high-risk 步驟停在 HITL。</li></ul><h3 id="階段五-治理與審計產品化-—-⬜-企業真正買單的部分" tabindex="-1">階段五：治理與審計產品化 — ⬜ 企業真正買單的部分 <a class="header-anchor" href="#階段五-治理與審計產品化-—-⬜-企業真正買單的部分" aria-label="Permalink to &quot;階段五：治理與審計產品化 — ⬜ 企業真正買單的部分&quot;">​</a></h3><ul><li>Audit log 實體化：execution log、policy decision log（含 <code>decision_id</code>）、approval history、source trace 落盤 + 查詢 API + 檢視頁。</li><li>輸出層 guardrails：<code>mask_fields</code> 實際應用於 tool 輸出；guardrails 三層面板（R4 M2）。</li><li>eval 擋 PR（PROJECT-PLAN Phase 2 待辦轉必辦）；Langfuse trace 常態化。</li><li>成效指標對外：任務完成率、接手率、平均 HITL 介入次數（回應趨勢 1）。</li><li><strong>驗收</strong>：任一 agent 行動可回答「依據什麼、誰批准、結果如何、失敗怎麼接手」四問。</li></ul><h2 id="_4-立即行動-本週可動工" tabindex="-1">4. 立即行動（本週可動工） <a class="header-anchor" href="#_4-立即行動-本週可動工" aria-label="Permalink to &quot;4. 立即行動（本週可動工）&quot;">​</a></h2><ol><li><code>tool.contract.ts</code> 草稿 + registry 型別改造（階段二地基，不動行為）。</li><li>Audit log 最小落盤：先寫 JSONL / in-memory store + <code>api.audit</code> 查詢 route，讓 <code>auditLogged</code> 不再是空頭布林（階段五提前拉一小塊，成本低、敘事價值高）。</li><li>ai-experience-plan 缺口②（AI 代填視覺標記）與 T-2026-023 申請畫面照原優先序推進——它們同時是階段一收尾與階段三前置。</li></ol><h2 id="_5-反面校正-避免走偏" tabindex="-1">5. 反面校正（避免走偏） <a class="header-anchor" href="#_5-反面校正-避免走偏" aria-label="Permalink to &quot;5. 反面校正（避免走偏）&quot;">​</a></h2><ul><li>不是「加聊天框」：chat 已有，價值在 tool contract 與治理。</li><li>不是「先做 fully autonomous」：每階段 agent 能力 ≤ 治理能力。</li><li>不是「MCP = 企業治理」：MCP 只是介面標準；治理在階段二、三、五。</li><li>不是「UI 不重要」：UI 轉為監督面、接管面、稽核面——R1 導覽、審核中心、audit 檢視頁都是這個角色。</li></ul>',36)])])}const g=e(r,[["render",c]]);export{p as __pageData,g as default};
